def is_plain_name(name: str) -> bool:
    """True when name is a single path component: no separators, not empty, not a dot segment."""
    ex is_plain_name("a.txt") == True
    ex is_plain_name("../secret") == False
    ex is_plain_name("sub/a.txt") == False
    if name == "" or name == "." or name == "..":
        return False
    for ch in name.chars():
        if ch == "/" or ch == "\\":
            return False
    return True

def read_one(name: str) -> str uses fs:
    """Text of the file name inside the current fs scope, or "" when it is missing or unreadable."""
    pre is_plain_name(name)
    return fs.read_text(name) else ""

def count_readable(names: list[str]) -> int uses fs:
    """Number of names that are readable files inside the notes directory; names outside it never reach the filesystem."""
    post out >= 0 and out <= names.len()
    n = 0
    with fs = fs.sub("notes"):
        for name in names:
            if not is_plain_name(name):
                continue
            text = read_one(name)
            if text != "":
                n += 1
    return n
